gates_run.command:
$ErrorActionPreference='Stop'
$m=Get-Content -Raw -LiteralPath 'docs/career-world-production/concept-briefs.json' | ConvertFrom-Json
$identityOnly=@('project/ticket-validation-automation@v1','project/sap-table-update-integration@v1','project/qc-alm-extractor@v1','project/atlassian-platform-automation@v1','project/atlassian-data-center-resilience@v1','project/client-devops-delivery-implementations@v1')
$employerUnlinked=@('skill/informatica@v1','skill/atlassian@v1','skill/ci-cd@v1')
$tracers=@('world/career-world@v1','city/ninjaone@v1','project/kaizen-metrics@v1','skill/go@v1','ambient/evergreen-cluster@v1')
function Asset([string]$id){@($m.assets | Where-Object id -eq $id)[0]}
if((@($m.assets | Where-Object category -eq 'project').asset_brief | Sort-Object -Unique).Count -ne 16){throw 'project briefs not unique'}
if((@($m.assets | Where-Object category -eq 'skill').asset_brief | Sort-Object -Unique).Count -ne 27){throw 'skill briefs not unique'}
foreach($a in $m.assets){
  if(@($a.reference_roles).Count -ne 1 -or @($a.avoid).Count -lt 1){throw "$($a.id) role/avoid"}
  if(-not $a.full_prompt.Contains($a.easter_egg_rule) -or ([regex]::Matches($a.full_prompt,'(?m)^Easter egg rule:')).Count -ne 1){throw "$($a.id) easter rule"}
  if($a.full_prompt -notmatch 'deterministic SVG'){throw "$($a.id) trace contract"}
  if($tracers -contains $a.id){
    if($a.reference_roles[0] -notmatch 'same-canonical tracer PNG' -or $a.full_prompt -notmatch 'same canonical tracer PNG' -or $a.full_prompt -notmatch 'never as an edit target, geometry source, coordinate truth'){throw "$($a.id) tracer reference policy"}
  } else {
    if($a.reference_roles[0] -notmatch 'art lead may assign a passing same-category image' -or $a.full_prompt -notmatch 'art lead explicitly assigns a passing same-category image' -or $a.full_prompt -notmatch 'never identity, topology, geometry, coordinates'){throw "$($a.id) non-tracer reference policy"}
  }
}
if((@($m.reference_policy.tracer_asset_ids|Sort-Object) -join '|') -ne (@($tracers|Sort-Object) -join '|')){throw 'tracer set'}
if(@($m.reference_policy.assigned_reference_images).Count -ne 0 -or $m.reference_policy.tracer_policy -notmatch 'same canonical asset' -or $m.reference_policy.tracer_policy -notmatch 'never edit targets, geometry sources, or coordinate truth' -or $m.reference_policy.non_tracer_policy -notmatch 'passing same-category image' -or $m.reference_policy.transfer_prohibition -notmatch 'never transfer canonical identity, topology, geometry, coordinates'){throw 'top reference policy'}
foreach($id in $identityOnly){$a=Asset $id;if($a.evidence_status -ne 'identity-only' -or $a.full_prompt -notmatch 'Derived only from the approved project name' -or $a.full_prompt -notmatch 'Explicit prohibition: do not imply factual architecture, a real campus, systems, metrics, outcomes, or skill symbolism'){throw "$id hold contract"}}
foreach($id in $employerUnlinked){if((Asset $id).evidence_status -ne 'employer-supported-unlinked'){throw "$id status"}}
if((Asset 'skill/java@v1').evidence_status -ne 'user-required-unplaced' -or (Asset 'skill/java@v1').full_prompt -notmatch 'currently unplaced'){throw 'Java contract'}
$ai=Asset 'skill/ai@v1'
if($ai.evidence_status -ne 'evidence-backed' -or $ai.full_prompt -notmatch 'Kaizen Metrics AWS Bedrock assistant' -or $ai.asset_brief -notmatch 'non-agentic analytical instrument pavilion' -or $ai.asset_brief -match 'star|decision chamber|inference wing' -or $ai.full_prompt -notmatch 'no decision center, autonomy, cognition, consciousness' -or $ai.full_prompt -notmatch 'star or sparkle silhouettes'){throw 'AI contract'}
$resilience=Asset 'project/atlassian-data-center-resilience@v1'
if($resilience.asset_brief -notmatch 'physically joined.+solid ground-level service necks' -or $resilience.asset_brief -match 'detached utility pods'){throw 'resilience connection'}
foreach($id in @('skill/vmware@v1','skill/macstadium@v1','skill/electron@v1')){if((Asset $id).evidence_status -ne 'evidence-backed'){throw "$id status"}}
$world=Asset 'world/career-world@v1'
foreach($anchor in @('NinjaOne \(340,370\)','Tanium \(800,350\)','Independent \(1240,380\)','ACE Hardware \(380,700\)','Column Technologies \(1200,700\)')){if($world.full_prompt -notmatch $anchor){throw "world anchor $anchor"}}
if(@($m.assets | Where-Object category -eq 'ambient' | Where-Object {$_.full_prompt -notmatch 'Ambient assets have no sign slot'}).Count){throw 'ambient sign-slot contract'}
'PASS distinct_project_briefs=16 distinct_skill_briefs=27 easter_rules=56 tracer_policy=5 nontracer_policy=51 ai=non-agentic-instrument resilience=connected'

$ErrorActionPreference='Stop'
$m=Get-Content -Raw -LiteralPath 'docs/career-world-production/concept-briefs.json' | ConvertFrom-Json
$links=@{
'project/kaizen-agent-platform@v1'=@('safe-writes','data-contract','Go','Redis','MCP','OpenAPI');
'project/vendy-vm-platform@v1'=@('workflow-orchestration','operator-control','data-contracts','Go','React','AWS','PostgreSQL','VMware','MacStadium');
'project/kaizen-metrics@v1'=@('Python','Databricks','workflow','data-contract','Go','PostgreSQL','Docker','AI','AWS');
'project/tanium-risk-assessment@v1'=@('Python','Go','workflow','operator-control','data-contract');
'project/uat-automation@v1'=@('C#','LocalDB','operator-control','workflow','data-contract');
'project/cablecar@v1'=@('React','Electron','workflow','operator-control','data-contract');
'project/xsearch@v1'=@('Manifest v3','data-contract','workflow','operator-control');
'project/tmatch-eolmatch@v1'=@('Go','data-contract');
'project/contextforge@v1'=@('context-compression','workflow','data-contract','TypeScript');
'project/career-world-portfolio@v1'=@('React','TypeScript','operator-control','data-contract')
}
foreach($id in $links.Keys){$p=@($m.assets|Where-Object id -eq $id)[0].full_prompt;foreach($term in $links[$id]){if($p -notmatch [regex]::Escape($term)){throw "$id missing $term"}}}
'PASS evidence_backed_project_link_terms=all_10_projects'
